{"code_snippet":""""
Run fib implementations and perform correctness checks and benchmarks.
This snippet defines the functions and runs tests, printing a JSON result.
"""
import json
import time
import traceback
import sys
from functools import lru_cache
from typing import Dict, Any, List

# --- fib_cache.py contents as definitions ---

def naive_recursive(n: int) -> int:
    if n < 0:
        raise ValueError("n must be non-negative")
    if n < 2:
        return n
    return naive_recursive(n - 1) + naive_recursive(n - 2)


@lru_cache(maxsize=None)
def cached_recursive(n: int) -> int:
    if n < 0:
        raise ValueError("n must be non-negative")
    if n < 2:
        return n
    return cached_recursive(n - 1) + cached_recursive(n - 2)


def iterative(n: int) -> int:
    if n < 0:
        raise ValueError("n must be non-negative")
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a


# --- test runner ---

def run_with_capture(func, n: int) -> Dict[str, Any]:
    record: Dict[str, Any] = {"n": n, "func": func.__name__}
    start = time.perf_counter()
    try:
        result = func(n)
        end = time.perf_counter()
        record.update({"result": repr(result), "time_s": end - start, "exception": None})
    except Exception:
        end = time.perf_counter()
        record.update({"result": None, "time_s": end - start, "exception": traceback.format_exc()})
    return record


def perform_tests() -> Dict[str, Any]:
    out: Dict[str, Any] = {}
    out["command"] = ["executed in code_analysis environment"]

    correctness_samples = [0, 1, 2, 5, 10, 50, 100, 500]
    naive_limit = 20

    oracle = {n: iterative(n) for n in correctness_samples}

    correctness_results: List[Dict[str, Any]] = []

    for n in correctness_samples:
        rec = run_with_capture(cached_recursive, n)
        rec["matches_oracle"] = (rec["exception"] is None and int(rec["result"]) == oracle[n])
        correctness_results.append(rec)

    for n in correctness_samples:
        if n <= naive_limit:
            rec = run_with_capture(naive_recursive, n)
            rec["matches_oracle"] = (rec["exception"] is None and int(rec["result"]) == oracle[n])
            correctness_results.append(rec)
        else:
            correctness_results.append({
                "n": n,
                "func": "naive_recursive",
                "result": None,
                "time_s": None,
                "exception": f"skipped (n>{naive_limit})",
                "matches_oracle": None,
            })

    failed_checks = [r for r in correctness_results if r.get("matches_oracle") is False]

    out["correctness_samples"] = correctness_samples
    out["correctness_results"] = correctness_results
    out["correctness_ok"] = len(failed_checks) == 0

    benchmarks = [
        {"n": 100, "label": "small"},
        {"n": 1000, "label": "medium"},
        {"n": 5000, "label": "large"},
    ]

    benchmark_results: List[Dict[str, Any]] = []
    funcs = [("iterative", iterative), ("cached_recursive", cached_recursive), ("naive_recursive", naive_recursive)]

    for b in benchmarks:
        n = b["n"]
        for name, func in funcs:
            if name == "naive_recursive" and n > naive_limit:
                benchmark_results.append({
                    "n": n,
                    "func": name,
                    "time_s": None,
                    "exception": f"skipped (n>{naive_limit})",
                })
                continue
            rec = run_with_capture(func, n)
            benchmark_results.append(rec)

    out["benchmarks"] = benchmarks
    out["benchmark_results"] = benchmark_results

    return out


if __name__ == "__main__":
    results = perform_tests()
    print(json.dumps(results, indent=2))
else:
    # When run via code_analysis, execute and capture
    results = perform_tests()
    print(json.dumps(results))
